css:
.toolbar {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  min-height: 140px;
  padding: 12px;
  border: 2px dashed #a1a1aa;
}

.btn {
  padding: 8px 14px;
  border: 0;
  border-radius: 6px;
  background: #3f3f46;
  color: #fafafa;
}

.note {
  height: 80px;
  padding: 8px 12px;
  background: #fed7aa;
  border: 1px solid #f97316;
  border-radius: 6px;
}

.save {
  align-self: flex-end; /* only this item */
  background: #f97316;
}
